from collections import deque


def bfs(graph, start):
    visited = {start}
    queue = deque([start])
    order = []
    while queue:
        v = queue.popleft()
        order.append(v)
        for n in sorted(graph.adjacency[v]):
            if n not in visited:
                visited.add(n)
                queue.append(n)
    for v in graph.adjacency:
        if v not in visited:
            order.append(v)
    return order
